import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';

@Component({
  selector: 'app-admin-login',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './admin-login.component.html'
})
export class AdminLoginComponent {
  username: string = '';
  password: string = '';
  errorMessage: string = '';
  loading: boolean = false;

  constructor(private router: Router) {}

  handleLogin(): void {
    if (!this.username || !this.password) {
      this.errorMessage = 'Please enter both User ID and Password';
      return;
    }

    this.loading = true;
    this.errorMessage = '';

    setTimeout(() => {
      this.loading = false;
      const storedUser = localStorage.getItem('admin_user_id') || 'admin';
      const storedPass = localStorage.getItem('admin_password') || 'admin123';

      const isValidUser = (this.username === 'admin' || this.username === storedUser);
      const isValidPass = (this.password === 'admin123' || this.password === 'password123' || this.password === storedPass);

      if (isValidUser && isValidPass) {
        sessionStorage.setItem('admin_logged_in', 'true');
        sessionStorage.setItem('admin_username', this.username);
        this.router.navigate(['/admin']);
      } else {
        this.errorMessage = 'Invalid User ID or Password.';
      }
    }, 300);
  }
}
<div style="max-width: 440px; margin: 40px auto; padding: 28px;" class="card">
  <div style="text-align: center; margin-bottom: 24px;">
    <div class="brand-icon" style="width: 48px; height: 48px; margin: 0 auto 12px; font-size: 1.4rem;">A</div>
    <h2 class="page-title" style="font-size: 1.5rem;">Admin Dashboard Sign In</h2>
    <p class="page-subtitle" style="font-size: 0.85rem;">Access Full CRUD Control Panel & SQL Server Database Settings</p>
  </div>

  <div *ngIf="errorMessage" style="background: rgba(239, 68, 68, 0.15); color: #fca5a5; border: 1px solid rgba(239, 68, 68, 0.3); border-radius: 8px; padding: 10px 14px; font-size: 0.85rem; margin-bottom: 20px;">
    ⚠️ {{ errorMessage }}
  </div>

  <form (ngSubmit)="handleLogin()">
    <div class="form-group">
      <label>User ID *</label>
      <input type="text" class="form-control" name="username" [(ngModel)]="username" required placeholder="Enter User ID">
    </div>

    <div class="form-group">
      <label>Password *</label>
      <input type="password" class="form-control" name="password" [(ngModel)]="password" required placeholder="Enter Password">
    </div>

    <button type="submit" class="btn btn-primary" style="width: 100%; justify-content: center; margin-top: 10px;" [disabled]="loading">
      {{ loading ? 'Signing In...' : 'Sign In to Admin Panel ➔' }}
    </button>
  </form>
</div>
